 * Grouped by what the host should do about it (see `docs/ffi-policy.md`):
 * domain validation, persistence, corrupt or newer data, cancellation,
 * lifecycle/resource, and internal failures. `reason` fields carry diagnostic
 * text for logs; they are not meant to be shown to users verbatim.
 */
sealed class ForgeAppException: kotlin.Exception() {
    
    class WouldUnderflow(
        ) : ForgeAppException() {
        override val message
            get() = ""
    }
    
    class WouldOverflow(
        ) : ForgeAppException() {
        override val message
            get() = ""
    }
    
    /**
     * An argument was outside what the operation accepts.
     */
    class InvalidInput(
        
        val `reason`: kotlin.String
        ) : ForgeAppException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    
    class PersistenceFailed(
        
        val `reason`: kotlin.String
        ) : ForgeAppException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    
    /**
     * Stored data is unreadable or invalid. Hosts may offer a reset.
     */
    class CorruptPersistence(
        
        val `reason`: kotlin.String
        ) : ForgeAppException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    
    /**
     * Stored data was written by a newer build. It is valid and must not be
     * reset; the user needs to update the app.
     */
    class UnsupportedSchemaVersion(
        
        val `found`: kotlin.UInt, 
        
        val `supported`: kotlin.UInt
        ) : ForgeAppException() {
        override val message
            get() = "found=${ `found` }, supported=${ `supported` }"
    }
    
    class PersistenceReadFailed(
        
        val `reason`: kotlin.String
        ) : ForgeAppException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    
    class StorageDirectoryUnavailable(
        ) : ForgeAppException() {
        override val message
            get() = ""
    }
    
    class Cancelled(
        ) : ForgeAppException() {
        override val message
            get() = ""
    }
    
    /**
     * The app instance has been shut down (or dropped); open a new one.
     */
    class ShutDown(
        ) : ForgeAppException() {
        override val message
            get() = ""
    }
    
    /**
     * Only one long-running operation runs at a time.
     */
    class OperationInProgress(
        ) : ForgeAppException() {
        override val message
            get() = ""
    }
    
    class InternalFailure(
        
        val `reason`: kotlin.String
        ) : ForgeAppException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    

